-- Sample users for development
--
-- Database setup (fully automated):
-- 1. The database is created when docker compose runs (PostgreSQL container)
-- 2. The users table is auto-generated by Hibernate (ddl-auto: update) when the Spring Boot app starts
-- 3. This script (data.sql) runs automatically and inserts sample data
--
-- No manual steps required - just run the application with docker compose

-- Clear table and reset IDs for predictable testing
TRUNCATE TABLE users RESTART IDENTITY CASCADE;

-- Insert sample users
INSERT INTO users (username, email, created_at)
VALUES
    ('alice', 'alice@example.com', CURRENT_TIMESTAMP),
    ('bob', 'bob@example.com', CURRENT_TIMESTAMP),
    ('carol', 'carol@example.com', CURRENT_TIMESTAMP);